#include <regex>
#include <iostream>
#include <string>

int main() {
    std::string input = "(123) 456 7890";  // Example phone number string
    std::regex phone_pattern(R"(\(\d{3}\)\s?\d{3}\s?\d{4})");  // Pattern with subexpression for area code
    std::smatch match;
    if (std::regex_search(input, match, phone_pattern)) {
        std::cout << "Full match: " << match[0] << std::endl;  // Entire matched string
        if (match.size() > 1) {
            std::cout << "Captured subexpression (area code): " << match[1] << std::endl;  // First subexpression
        }
    } else {
        std::cout << "No match found." << std::endl;
    }
    return 0;
}
